class Solution {
    unordered_map<Node*, Node*> parent;

    void build(Node* node) {
        for (Node* child : node->children) {
            parent[child] = node;
            build(child);
        }
    }

    void replaceChild(Node* owner, Node* oldNode, Node* newNode) {
        if (!owner) {
            return;
        }
        for (Node*& child : owner->children) {
            if (child == oldNode) {
                child = newNode;
                return;
            }
        }
    }

    void removeChild(Node* owner, Node* child) {
        if (!owner) {
            return;
        }
        auto& children = owner->children;
        children.erase(remove(children.begin(), children.end(), child),
                       children.end());
    }

public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        parent.clear();
        parent[root] = nullptr;
        build(root);
        Node* oldParentP = parent[p];
        Node* oldParentQ = parent[q];
        if (oldParentP == q) {
            return root;
        }
        bool qInsideP = false;
        for (Node* current = q; current; current = parent[current]) {
            if (current == p) {
                qInsideP = true;
                break;
            }
        }
        if (qInsideP) {
            removeChild(oldParentQ, q);
            replaceChild(oldParentP, p, q);
            if (!oldParentP) {
                root = q;
            }
        } else {
            removeChild(oldParentP, p);
        }
        q->children.push_back(p);
        return root;
    }
};
